    O=I.copy()
    mk=[(r,c,int(I[r,c])) for r,c in zip(*np.where((I!=0)&(I!=2)))]
    above=[m for m in mk if m[0]<r0]; below=[m for m in mk if m[0]>r1]
    def strip_rect(rows_range):
